procedure @@proc@@(p_n in number) is
  l_hit number := 0;
begin
  <<outer>>
  for i in 1 .. p_n loop
    for j in 1 .. 3 loop
      continue outer when j > i;
      l_hit := l_hit + j;
    end loop;
    commit; -- @expect
  end loop outer;
  dbms_output.put_line(l_hit);
end @@proc@@;

procedure @@proc@@(p_max in number, p_mode in number) is
  l_i number := 0;
begin
  while l_i < p_max loop
    l_i := l_i + 1;
    case p_mode
      when 3 then
        @@proc2@@(l_i);
      else
        null;
    end case;
    -- end loop;  (this comment is not a real terminator)
    if mod(l_i, 4) = 0 then
      dbms_output.put_line('tick');
    end if;
    rollback; -- @expect
  end loop;
end @@proc@@;

procedure @@proc@@(p_n in number) is
  l_k number := 0;
  procedure step(p_i in number) is
  begin
    for r in 1 .. p_i loop
      l_k := l_k + r;
    end loop;
  end step;
begin
  loop
    l_k := l_k + 1;
    step(l_k);
    COMMIT; -- @expect
    exit when l_k >= p_n; -- end loop;
  end loop;
end @@proc@@;

procedure @@proc@@(p_n in number) is
  l_i number := 0;
begin
  while l_i < p_n loop
    l_i := l_i + 1;
    @@proc2@@(l_i);
    $IF $$flush_each $THEN
    commit; -- @expect
    $END
  end loop;
end @@proc@@;

procedure @@proc@@(p_n in number) is
  l_msg varchar2(100) := q'[commit; rollback; end loop;]';
  l_i number := 0;
begin
	for i in 1 .. p_n loop
		l_i := l_i + 1;
		if mod(l_i, 100) = 0 then commit; end if; -- @expect
	end loop;
	dbms_output.put_line(l_msg);
end @@proc@@;

