procedure @@proc@@(p_n in number) is
  l_hit number := 0;
begin
  <<outer>>
  for i in 1 .. p_n loop
    for j in 1 .. 3 loop
      if j > i then
        exit;
      end if;
      l_hit := l_hit + case when j = i then 2 else 0 end;
    end loop;
  end loop outer;
  commit;
  dbms_output.put_line(l_hit);
end @@proc@@;

procedure @@proc@@(p_n in number) is
  l_msg varchar2(200);
begin
  for i in 1 .. p_n loop
    /* the caller does the commit; rollback; only on failure */
    l_msg := q'[commit; rollback;]';
    dbms_output.put_line(l_msg || i); -- commit;
  end loop;
end @@proc@@;

procedure @@proc@@(p_n in number) is
begin
  for i in 1 .. p_n loop
    savepoint sp_item;
    begin
      @@proc2@@(i);
    exception
      when dup_val_on_index then
	ROLLBACK
	  TO
	  SAVEPOINT sp_item;
    end;
  end loop;
end @@proc@@;

procedure @@proc@@(p_n in number) is
  l_cnt number := 0;
  procedure checkpoint_work is
  begin
    commit;
  end checkpoint_work;
begin
  for i in 1 .. p_n loop
    l_cnt := l_cnt + 1;
    checkpoint_work;
  end loop;
  dbms_output.put_line(l_cnt);
end @@proc@@;

procedure @@proc@@(p_n in number) is
  l_a number := 0;
  l_b number := 0;
begin
  for i in 1 .. p_n loop
    case
      when mod(i, 2) = 0 then l_a := l_a + i;
      else l_b := l_b + i;
    end case;
  end loop;
  commit;
  while l_b > p_n loop
    if l_b > l_a then l_b := l_b - p_n; else l_b := 0; end if;
  end loop;
  rollback;
end @@proc@@;
